const item = $input.item.json;
const formData = $('Form - Request Life Event Simulation').first().json;

const accounts = item.accounts || [];
const transactions = item.recentTransactions || [];

const totalAssets = accounts
  .filter(a => ['checking', 'savings', 'investment'].includes((a.type || '').toLowerCase()))
  .reduce((sum, a) => sum + (parseFloat(a.balance) || 0), 0);

const totalLiabilities = accounts
  .filter(a => ['credit', 'loan'].includes((a.type || '').toLowerCase()))
  .reduce((sum, a) => sum + Math.abs(parseFloat(a.balance) || 0), 0);

const netWorth = Math.round((totalAssets - totalLiabilities) * 100) / 100;

// Recent transactions sampled over roughly 3 months; positive amount = income, negative = expense
const monthlyIncome = Math.round(
  (transactions.filter(t => (parseFloat(t.amount) || 0) > 0)
    .reduce((sum, t) => sum + (parseFloat(t.amount) || 0), 0) / 3) * 100
) / 100;

const monthlyExpenses = Math.round(
  (Math.abs(transactions.filter(t => (parseFloat(t.amount) || 0) < 0)
    .reduce((sum, t) => sum + (parseFloat(t.amount) || 0), 0)) / 3) * 100
) / 100;

const emergencyFundMonths = monthlyExpenses > 0 ? Math.round((totalAssets / monthlyExpenses) * 10) / 10 : null;

const marketMeanMonthlyReturn = item.meanMonthlyReturn ?? 0.006;
const marketStdDevMonthlyReturn = item.stdDevMonthlyReturn ?? 0.04;

const lifeEvent = {
  type: formData['Event Type'] || 'Custom',
  homePrice: parseFloat(formData['Home Price']) || 0,
  downPaymentPct: parseFloat(formData['Down Payment %']) || 20,
  jobLossDurationMonths: parseInt(formData['Job Loss Duration Months'], 10) || 0
};

const horizonMonths = parseInt(formData['Simulation Horizon Months'], 10) || 60;

return {
  json: {
    netWorth, totalAssets, totalLiabilities,
    monthlyIncome, monthlyExpenses, emergencyFundMonths,
    marketMeanMonthlyReturn, marketStdDevMonthlyReturn,
    lifeEvent, horizonMonths
  }
};

const item = $input.item.json;
const {
  netWorth, monthlyIncome, monthlyExpenses,
  marketMeanMonthlyReturn, marketStdDevMonthlyReturn,
  lifeEvent, horizonMonths
} = item;

const ITERATIONS = 1000;

function randomNormal(mean, stdDev) {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  const z = Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
  return mean + z * stdDev;
}

const endingNetWorths = [];
let shortfallCount = 0;

for (let i = 0; i < ITERATIONS; i++) {
  let balance = netWorth;
  let ranOutOfMoney = false;

  for (let month = 1; month <= horizonMonths; month++) {
    let income = monthlyIncome;
    let expenses = monthlyExpenses;

    if ((lifeEvent.type === 'Lose a Job' || lifeEvent.type === 'Both') && month <= (lifeEvent.jobLossDurationMonths || 0)) {
      income = 0;
    }

    if (lifeEvent.type === 'Buy a House' || lifeEvent.type === 'Both') {
      if (month === 1) {
        const downPayment = (lifeEvent.homePrice || 0) * ((lifeEvent.downPaymentPct || 20) / 100);
        balance -= downPayment;
      }
      const loanAmount = (lifeEvent.homePrice || 0) * (1 - (lifeEvent.downPaymentPct || 20) / 100);
      const monthlyMortgage = loanAmount > 0 ? (loanAmount * 0.005) : 0; // approx principal+interest at ~6%/yr
      expenses += monthlyMortgage;
    }

    const marketReturn = randomNormal(marketMeanMonthlyReturn, marketStdDevMonthlyReturn);
    balance = balance * (1 + marketReturn) + (income - expenses);

    if (balance < 0) ranOutOfMoney = true;
  }

  endingNetWorths.push(Math.round(balance * 100) / 100);
  if (ranOutOfMoney) shortfallCount++;
}

endingNetWorths.sort((a, b) => a - b);
const percentile = (p) => endingNetWorths[Math.floor((p / 100) * (endingNetWorths.length - 1))];

const simulation = {
  iterations: ITERATIONS,
  horizonMonths,
  p10EndingNetWorth: percentile(10),
  p50EndingNetWorth: percentile(50),
  p90EndingNetWorth: percentile(90),
  shortfallProbabilityPct: Math.round((shortfallCount / ITERATIONS) * 1000) / 10
};

return { json: { ...item, simulation } };

